{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "Acarbose, a highly polar poorly absorbed saccharide-like drug, has an absolute oral bioavailability of <2% in humans based on plasma and urinary recovery versus IV administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Pentosan polysulfate, a highly polar sulfated polysaccharide, has an oral bioavailability of only 0.5-1% compared with i.v. administration in healthy subjects.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Furosemide acyl glucuronide, a highly polar conjugated metabolite, has an oral bioavailability of 0.15 (15%) in humans, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Baicalin, a polar glycoside with poor permeability, has minimal oral bioavailability in humans, consistent with low systemic exposure after oral dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Dextran sulfate, a highly polar sulfated macromolecule, has poor oral bioavailability and is not practically useful as an oral agent.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All available experimental analogues are highly polar, ionized, poorly permeable molecules with measured or reported oral bioavailability well below 20%, strongly supporting a low absolute oral bioavailability prediction for the query.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement is available for the query molecule itself.",
    "Possible active transport or carrier-mediated absorption for the query is not addressed by the available evidence.",
    "Exact structural identity of the query relative to the analogue molecules is not directly visible in this ablation."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

